use rand::Rng;
use std::io::{self, Write};

fn rc4(key: &[u8], input: &[u8]) -> Vec<u8> {
    let mut s: Vec<u8> = (0..=255).collect();
    let mut j: usize = 0;
    for i in 0..256 {
        j = (j + (s[i] as usize) + (key[i % key.len()] as usize)) % 256;
        s.swap(i, j);
    }
    let mut i = 0;
    let mut j = 0;
    let mut out = Vec::with_capacity(input.len());
    for byte in input.iter() {
        i = (i + 1) % 256;
        j = (j + (s[i] as usize)) % 256;
        s.swap(i, j);
        let k = s[((s[i] as usize) + (s[j] as usize)) % 256];
        out.push(byte ^ k);
    }
    out
}

fn main() {
    let mut rng = rand::thread_rng();
    let flag = include_bytes!("flag.txt");
    loop {
        print!("Input (hex): ");
        io::stdout().flush().unwrap();
        let mut input_hex = String::new();
        io::stdin().read_line(&mut input_hex).unwrap();
        let input = match hex::decode(input_hex.trim()) {
            Ok(v) => v,
            Err(_) => { println!("Invalid hex"); continue; }
        };
        let key: Vec<u8> = (0..16).map(|_| rng.gen()).collect();
        let mut data = Vec::with_capacity(input.len() + flag.len());
        data.extend(&input);
        data.extend(flag);
        let ct = rc4(&key, &data);
        println!("Output (hex): {}", hex::encode(&ct));
    }
}

