from pwn import remote
import binascii
import time
import sys
import os

HOST = 'crypto.chal.csaw.io'
PORT = 4512

def query_oracle(pt_bytes):
    conn = remote(HOST, PORT, timeout=6, level='error')
    pt_hex = binascii.hexlify(pt_bytes).decode()
    conn.recvuntil(b'Input (hex): ')
    conn.sendline(pt_hex.encode())
    out_hex = b''
    while b'Output (hex): ' not in out_hex:
        l = conn.recvline(timeout=6)
        if l == b'':
            conn.close()
            return None
        out_hex += l
    conn.close()
    lines = out_hex.split(b'\n')
    for l in lines:
        if b'Output (hex): ' in l:
            return binascii.unhexlify(l.split(b':')[1].strip())
    return None

def main():
    results = {}
    for N in range(4):
        print(f'[*] Querying with input length N={N} ({N} zero bytes)...')
        ct = query_oracle(b'\x00'*N)
        results[N] = ct
        if ct:
            print(f'CT{N}:', binascii.hexlify(ct).decode())
        else:
            print(f'CT{N}: No ciphertext returned!')
        time.sleep(2)
    with open('/home/ctfplayer/ctf_files/ct_lengths.txt', 'w') as f:
        for k, v in results.items():
            f.write(f'N={k}: {binascii.hexlify(v).decode() if v else "ERR"}\n')

if __name__ == '__main__':
    main()

